// Convierte lo que escribiste en el formulario en una lista prolija de correos.
const form = $input.first().json;
const texto = String(form.correos ?? '');
const formato = /^[^\s@,;]+@[^\s@,;]+\.[^\s@,;]{2,}$/;

const vistos = new Set();
const correos = [];
const descartados = [];
for (const parte of texto.split(/[\s,;]+/)) {
  const correo = parte.trim().toLowerCase();
  if (!correo || vistos.has(correo)) continue; // vacíos y repetidos afuera
  vistos.add(correo);
  if (formato.test(correo)) correos.push(correo);
  else descartados.push(correo);
}

const redirect = String(form.redirect_url ?? '').trim();
return [
  {
    json: {
      correos,
      descartados,
      redirect_url: /^https?:\/\//.test(redirect) ? redirect : '',
    },
  },
];

// Junta cada respuesta de Clerk con su correo y arma el texto de la página final.
const enviados = $('Un ítem por correo').all();
const respuestas = $input.all();
const descartados = $('Limpiar la lista').first().json.descartados;

const invitadas = [];
const conError = [];
respuestas.forEach((r, i) => {
  const correo = enviados[i]?.json.email ?? '(sin correo)';
  const status = r.json.statusCode;
  const cuerpo = r.json.body ?? {};
  if (status >= 200 && status < 300) {
    invitadas.push({ correo, id: cuerpo.id, estado: cuerpo.status, vence: cuerpo.expires_at ? new Date(cuerpo.expires_at).toISOString().slice(0, 10) : null });
  } else {
    const e = Array.isArray(cuerpo.errors) ? cuerpo.errors[0] : null;
    conError.push({ correo, status, codigo: e?.code ?? null, motivo: e?.long_message ?? e?.message ?? r.json.error?.message ?? 'Clerk no respondió' });
  }
});

const lineas = [];
if (invitadas.length) lineas.push('Invitadas: ' + invitadas.map((x) => x.correo).join(', ') + '.');
if (conError.length) lineas.push('No se pudo invitar: ' + conError.map((x) => `${x.correo} (${x.status}: ${x.motivo})`).join('; ') + '.');
if (descartados.length) lineas.push('Descartados por el formato: ' + descartados.join(', ') + '.');

return [
  {
    json: {
      titulo: conError.length ? `Listo, con ${conError.length} para revisar` : 'Invitaciones enviadas',
      mensaje: lineas.join(' '),
      invitadas,
      con_error: conError,
      descartados,
    },
  },
];
